// Deterministic funding and financial calculations. Never generated by a model.
// All amounts are integer cents. `null` means "Not established" — never zero.

export type CommitmentStage = "prospect" | "application" | "conditional_pledge" | "binding_commitment";
export type Restriction = "acquisition" | "operating" | "capital_repair" | "program" | "unrestricted" | null;

export interface Commitment {
  id: string;
  funder: string;
  stage: CommitmentStage;
  amount_cents: number | null;
  restricted_to: Restriction;
  expires_on: string | null; // YYYY-MM-DD
}

export interface Receipt {
  id: string;
  commitment_id: string | null;
  amount_cents: number;
  received_on: string;
}

export interface FundingPosition {
  cashReceivedCents: number;
  remainingCommittedCents: number;
  /** cash received + remaining binding commitments; excludes conditional pledges and applications */
  securedCents: number;
  /** true when a binding commitment has an unknown amount, so securedCents is a floor */
  securedIncomplete: boolean;
  conditionalPledgesCents: number;
  conditionalIncomplete: boolean;
  applicationsCount: number;
  prospectsCount: number;
  expiredCommitmentIds: string[];
  capitalTargetCents: number | null;
  /** null when the target is unknown or secured is incomplete */
  gapCents: number | null;
  byRestriction: Record<string, { cashCents: number; remainingCommittedCents: number }>;
}

function assertCents(n: number, label: string) {
  if (!Number.isSafeInteger(n)) throw new Error(`${label} must be integer cents, got ${n}`);
}

export function computeFundingPosition(
  commitments: Commitment[],
  receipts: Receipt[],
  capitalTargetCents: number | null,
  asOf: string,
): FundingPosition {
  const linked = new Map<string, number>();
  let cash = 0;
  const byRestriction: FundingPosition["byRestriction"] = {};
  const bucket = (r: Restriction) => {
    const k = r ?? "restriction_not_established";
    byRestriction[k] ??= { cashCents: 0, remainingCommittedCents: 0 };
    return byRestriction[k];
  };
  const commitmentById = new Map(commitments.map((c) => [c.id, c]));

  for (const r of receipts) {
    assertCents(r.amount_cents, "receipt");
    if (r.amount_cents <= 0) throw new Error("receipt amount must be positive");
    cash += r.amount_cents;
    const c = r.commitment_id ? commitmentById.get(r.commitment_id) : undefined;
    bucket(c ? c.restricted_to : null).cashCents += r.amount_cents;
    if (r.commitment_id) linked.set(r.commitment_id, (linked.get(r.commitment_id) ?? 0) + r.amount_cents);
  }

  let remaining = 0;
  let securedIncomplete = false;
  let conditional = 0;
  let conditionalIncomplete = false;
  let applications = 0;
  let prospects = 0;
  const expired: string[] = [];

  for (const c of commitments) {
    if (c.amount_cents !== null) assertCents(c.amount_cents, "commitment");
    const isExpired = c.expires_on !== null && c.expires_on < asOf;
    switch (c.stage) {
      case "binding_commitment": {
        if (isExpired) {
          expired.push(c.id);
          break;
        }
        if (c.amount_cents === null) {
          securedIncomplete = true;
          break;
        }
        const rem = Math.max(c.amount_cents - (linked.get(c.id) ?? 0), 0);
        remaining += rem;
        bucket(c.restricted_to).remainingCommittedCents += rem;
        break;
      }
      case "conditional_pledge":
        if (isExpired) {
          expired.push(c.id);
          break;
        }
        if (c.amount_cents === null) conditionalIncomplete = true;
        else conditional += c.amount_cents;
        break;
      case "application":
        applications++;
        break;
      case "prospect":
        prospects++;
        break;
    }
  }

  const secured = cash + remaining;
  const gap =
    capitalTargetCents === null || securedIncomplete ? null : Math.max(capitalTargetCents - secured, 0);

  return {
    cashReceivedCents: cash,
    remainingCommittedCents: remaining,
    securedCents: secured,
    securedIncomplete,
    conditionalPledgesCents: conditional,
    conditionalIncomplete,
    applicationsCount: applications,
    prospectsCount: prospects,
    expiredCommitmentIds: expired,
    capitalTargetCents,
    gapCents: gap,
    byRestriction,
  };
}

// ---------------------------------------------------------------------------
// Sources and uses / operating views
// ---------------------------------------------------------------------------
export interface FinancialLine {
  id: string;
  label: string;
  line_kind: "source" | "use" | "income" | "expense";
  boundary: "property" | "operator" | "program";
  period: string;
  amount_cents: number | null;
  assumption_state: "proposed" | "accepted" | "rejected";
  internal_transfer_key: string | null;
}

export interface Total {
  /** sum of established amounts */
  knownCents: number;
  /** labels of lines whose amount is not established */
  unknownLines: string[];
  /** null when any contributing line is unknown */
  totalCents: number | null;
}

function total(lines: FinancialLine[]): Total {
  let known = 0;
  const unknown: string[] = [];
  for (const l of lines) {
    if (l.amount_cents === null) unknown.push(l.label);
    else {
      assertCents(l.amount_cents, l.label);
      known += l.amount_cents;
    }
  }
  return { knownCents: known, unknownLines: unknown, totalCents: unknown.length ? null : known };
}

/** Base-case view: rejected assumptions never enter; proposed ones are reported separately. */
export function sourcesAndUses(lines: FinancialLine[]) {
  const base = lines.filter((l) => l.assumption_state === "accepted");
  const proposed = lines.filter((l) => l.assumption_state === "proposed");
  const sources = total(base.filter((l) => l.line_kind === "source"));
  const uses = total(base.filter((l) => l.line_kind === "use"));
  const gap =
    sources.totalCents === null || uses.totalCents === null ? null : uses.totalCents - sources.totalCents;
  return {
    sources,
    uses,
    gapCents: gap,
    proposedExcluded: proposed.map((l) => l.label),
    rejectedExcluded: lines.filter((l) => l.assumption_state === "rejected").map((l) => l.label),
  };
}

/**
 * Operating view for one boundary or combined. In the combined view, internal transfers
 * (e.g. operator rent expense == property rent income) are eliminated so they are not
 * double counted. Property rent is operating income, never a donation.
 */
export function operatingView(lines: FinancialLine[], boundary: FinancialLine["boundary"] | "combined", period: string) {
  let scoped = lines.filter(
    (l) =>
      l.assumption_state === "accepted" &&
      l.period === period &&
      (l.line_kind === "income" || l.line_kind === "expense") &&
      (boundary === "combined" || l.boundary === boundary),
  );
  const eliminated: string[] = [];
  if (boundary === "combined") {
    const keys = new Map<string, FinancialLine[]>();
    for (const l of scoped) if (l.internal_transfer_key) keys.set(l.internal_transfer_key, [...(keys.get(l.internal_transfer_key) ?? []), l]);
    const drop = new Set<string>();
    for (const [k, group] of keys) {
      const inc = group.filter((l) => l.line_kind === "income");
      const exp = group.filter((l) => l.line_kind === "expense");
      if (inc.length && exp.length) {
        group.forEach((l) => drop.add(l.id));
        eliminated.push(k);
      }
    }
    scoped = scoped.filter((l) => !drop.has(l.id));
  }
  const income = total(scoped.filter((l) => l.line_kind === "income"));
  const expense = total(scoped.filter((l) => l.line_kind === "expense"));
  const net = income.totalCents === null || expense.totalCents === null ? null : income.totalCents - expense.totalCents;
  return { income, expense, netCents: net, eliminatedTransfers: eliminated };
}

export function formatCents(c: number | null | undefined, opts: { comparator?: string } = {}): string {
  if (c === null || c === undefined) return "Not established";
  const s = (c / 100).toLocaleString("en-US", { style: "currency", currency: "USD", maximumFractionDigits: c % 100 === 0 ? 0 : 2 });
  switch (opts.comparator) {
    case "below":
      return `below ${s}`;
    case "above":
      return `above ${s}`;
    case "approximately":
      return `≈ ${s}`;
    default:
      return s;
  }
}
